import { useSimulation } from '@services/SimulationContext';
import { useState } from 'react';
import { TraitType } from '../types';

export function GeneticAnalysis() {
  const { simulationData } = useSimulation();
  const [selectedSpecies, setSelectedSpecies] = useState<string | null>(null);

  if (!simulationData || !simulationData.species || simulationData.species.length === 0) {
    return (
      <div className="card">
        <h3 className="text-lg font-semibold mb-4">🧬 Analyse Génétique - Serina</h3>
        <div className="animate-pulse">
          <div className="h-4 bg-gray-200 rounded w-1/3 mb-4"></div>
          <div className="space-y-3">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="h-4 bg-gray-200 rounded"></div>
            ))}
          </div>
        </div>
        <p className="text-gray-500 mt-4">Chargement des données d'évolution de Serina...</p>
      </div>
    );
  }

  const species = simulationData.species;
  const currentSpecies = selectedSpecies 
    ? species.find(s => s.name === selectedSpecies) 
    : species[0];

  if (!currentSpecies) {
    return (
      <div className="card">
        <h3 className="text-lg font-semibold mb-4">🧬 Analyse Génétique - Serina</h3>
        <p className="text-gray-500">Aucune espèce disponible pour l'analyse</p>
      </div>
    );
  }

  const getSpeciesOrigin = (name: string): string => {
    if (name.toLowerCase().includes('canaria')) return 'Descendant direct des canaris originaux de Serina';
    if (name.toLowerCase().includes('xiphophorus')) return 'Lignée des poissons porte-épée, colonisant les eaux douces';
    if (name.toLowerCase().includes('poecilia')) return 'Famille des guppys et mollys, diversifiée dans les zones humides';
    if (name.toLowerCase().includes('gryllus')) return 'Grillons adaptés aux prairies et zones herbacées';
    if (name.toLowerCase().includes('solenopsis')) return 'Fourmis de feu colonisant les sols riches';
    if (name.toLowerCase().includes('achatina')) return 'Escargots géants des forêts humides de Serina';
    return 'Espèce endémique évoluée sur Serina';
  };

  const getTraitColor = (value: number) => {
    if (value >= 0.8) return 'text-green-600 bg-green-100';
    if (value >= 0.6) return 'text-blue-600 bg-blue-100';
    if (value >= 0.4) return 'text-yellow-600 bg-yellow-100';
    if (value >= 0.2) return 'text-orange-600 bg-orange-100';
    return 'text-red-600 bg-red-100';
  };

  const getTraitDescription = (trait: TraitType, value: number): string => {
    const descriptions = {
      [TraitType.SIZE]: value > 0.8 ? 'Grande taille (domination territoriale)' : value > 0.4 ? 'Taille moyenne' : 'Petite taille (agilité accrue)',
      [TraitType.SPEED]: value > 0.8 ? 'Très rapide (migration efficace)' : value > 0.4 ? 'Vitesse modérée' : 'Lent (économie d\'énergie)',
      [TraitType.INTELLIGENCE]: value > 0.8 ? 'Très intelligent (utilisation d\'outils)' : value > 0.4 ? 'Intelligence modérée' : 'Intelligence basique',
      [TraitType.SOCIABILITY]: value > 0.8 ? 'Très social (comportement grégaire)' : value > 0.4 ? 'Social modéré' : 'Solitaire',
      [TraitType.ADAPTABILITY]: value > 0.8 ? 'Adaptation rapide aux changements' : value > 0.4 ? 'Adaptation modérée' : 'Adaptation lente',
      [TraitType.METABOLISM]: value > 0.8 ? 'Métabolisme très efficace' : value > 0.4 ? 'Métabolisme normal' : 'Métabolisme lent',
      [TraitType.STRENGTH]: value > 0.8 ? 'Très fort (combat/construction)' : value > 0.4 ? 'Force modérée' : 'Faible (furtivité)',
      [TraitType.LONGEVITY]: value > 0.8 ? 'Longévité exceptionnelle' : value > 0.4 ? 'Durée de vie normale' : 'Vie courte (reproduction rapide)',
      [TraitType.RESISTANCE]: value > 0.8 ? 'Résistance aux maladies élevée' : value > 0.4 ? 'Résistance modérée' : 'Vulnérable aux pathogènes',
      [TraitType.VISION_RANGE]: value > 0.8 ? 'Vision exceptionnelle (prédation)' : value > 0.4 ? 'Vision normale' : 'Vision limitée',
      [TraitType.CAMOUFLAGE]: value > 0.8 ? 'Camouflage parfait' : value > 0.4 ? 'Camouflage modéré' : 'Très visible',
      [TraitType.REPRODUCTION_RATE]: value > 0.8 ? 'Reproduction très rapide' : value > 0.4 ? 'Reproduction normale' : 'Reproduction lente'
    };
    return descriptions[trait] || 'Trait inconnu';
  };

  const traitNames = {
    [TraitType.SIZE]: 'Taille corporelle',
    [TraitType.SPEED]: 'Vitesse',
    [TraitType.STRENGTH]: 'Force physique',
    [TraitType.INTELLIGENCE]: 'Intelligence',
    [TraitType.LONGEVITY]: 'Longévité',
    [TraitType.RESISTANCE]: 'Résistance aux maladies',
    [TraitType.METABOLISM]: 'Métabolisme',
    [TraitType.SOCIABILITY]: 'Sociabilité',
    [TraitType.ADAPTABILITY]: 'Adaptabilité',
    [TraitType.VISION_RANGE]: 'Portée visuelle',
    [TraitType.CAMOUFLAGE]: 'Camouflage',
    [TraitType.REPRODUCTION_RATE]: 'Taux de reproduction'
  };

  return (
    <div className="card">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-lg font-semibold">🧬 Analyse Génétique - Monde de Serina</h3>
        {species.length > 1 && (
          <select 
            value={selectedSpecies || currentSpecies.name}
            onChange={(e) => setSelectedSpecies(e.target.value)}
            className="px-3 py-1 border rounded-md text-sm"
          >
            {species.map(s => (
              <option key={s.id} value={s.name}>{s.name}</option>
            ))}
          </select>
        )}
      </div>

      <div className="mb-6 p-4 bg-blue-50 rounded-lg">
        <h4 className="font-semibold text-blue-800">{currentSpecies.name}</h4>
        <p className="text-sm text-blue-600 mt-1">{getSpeciesOrigin(currentSpecies.name)}</p>
        <div className="grid grid-cols-2 gap-4 mt-3 text-sm">
          <div>
            <span className="font-medium">Population:</span> {currentSpecies.populationCount.toLocaleString()}
          </div>
          <div>
            <span className="font-medium">Génération:</span> {currentSpecies.generationSpan}
          </div>
          <div>
            <span className="font-medium">Niche écologique:</span> {currentSpecies.ecologicalNiche}
          </div>
          <div>
            <span className="font-medium">Risque d'extinction:</span> 
            <span className={`ml-1 px-2 py-1 rounded text-xs ${
              currentSpecies.extinctionRisk > 0.7 ? 'bg-red-100 text-red-700' :
              currentSpecies.extinctionRisk > 0.4 ? 'bg-yellow-100 text-yellow-700' :
              'bg-green-100 text-green-700'
            }`}>
              {(currentSpecies.extinctionRisk * 100).toFixed(1)}%
            </span>
          </div>
        </div>
      </div>

      <h4 className="font-semibold mb-4">📊 Profil génétique de l'espèce</h4>
      <div className="space-y-3">
        {Object.entries(traitNames).map(([trait, name]) => {
          const value = currentSpecies.averageTrait[trait as TraitType] || 0;
          return (
            <div key={trait} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
              <div className="flex-1">
                <div className="flex justify-between items-center mb-1">
                  <span className="font-medium text-sm">{name}</span>
                  <span className={`px-2 py-1 rounded text-xs font-medium ${getTraitColor(value)}`}>
                    {(value * 100).toFixed(1)}%
                  </span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div 
                    className="bg-blue-500 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${value * 100}%` }}
                  />
                </div>
                <p className="text-xs text-gray-600 mt-1">
                  {getTraitDescription(trait as TraitType, value)}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      <div className="mt-6 p-4 bg-amber-50 border border-amber-200 rounded-lg">
        <h5 className="font-semibold text-amber-800 mb-2">🌍 Contexte évolutif - Serina</h5>
        <p className="text-sm text-amber-700">
          Cette espèce évolue dans le monde de Serina, un écosystème unique où seuls les oiseaux, 
          quelques insectes, poissons et invertébrés ont colonisé une planète vierge. 
          Chaque trait reflète l'adaptation aux conditions environnementales spécifiques de ce monde.
        </p>
      </div>
    </div>
  );
}